<style>
.lp-cookie-panel{position:fixed;bottom:16px;left:16px;right:16px;margin:auto;max-width:760px;z-index:1000;background:#fffef9;color:#153e39;border:1px solid #cbd8cf;border-radius:18px;padding:20px 24px;box-shadow:0 8px 35px #153e3926;font:14px/1.5 system-ui,sans-serif}.lp-cookie-panel[hidden]{display:none}.lp-cookie-panel h2{font:400 24px/1.2 Georgia,serif;margin:0 0 8px}.lp-cookie-panel p{margin:8px 0}.lp-cookie-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:14px}.lp-cookie-actions button{flex:1;min-height:44px;border:1px solid #00786e;border-radius:24px;padding:10px 14px;background:#eaf1e7;color:#153e39;font:600 14px/1.4 system-ui;cursor:pointer}.lp-cookie-actions button[data-cookie-choice="yes"]{background:#00786e;color:#fff}.lp-cookie-actions button[data-cookie-choice="yes"]:hover{background:#005f57}.lp-cookie-actions button[data-cookie-choice="no"]:hover{background:#dce9d7}.lp-cookie-actions button:disabled{opacity:.6;cursor:wait}.lp-cookie-link{border:0!important;background:transparent!important;color:#00786e!important;font:inherit!important;padding:0!important;box-shadow:none!important;text-decoration:underline;cursor:pointer}.lp-cookie-panel a{color:#00786e}.lp-cookie-panel :focus-visible{outline:3px solid #bc8500;outline-offset:3px}@media(max-width:500px){.lp-cookie-panel{padding:18px;bottom:8px;left:8px;right:8px}.lp-cookie-actions{flex-direction:column}}
</style>
<section id="lpCookiePanel" class="lp-cookie-panel" aria-labelledby="lpCookieTitle" @if(\App\Support\CookieChoice::value(request())!==null) hidden @endif>
<h2 id="lpCookieTitle"></h2><p id="lpCookieText"></p><a id="lpCookiePrivacy" href="/privacy">Privacy</a><div class="lp-cookie-actions"><button type="button" data-cookie-choice="no"></button><button type="button" data-cookie-choice="yes"></button></div><p id="lpCookieError" role="status"></p>
</section>
<script nonce="{{ request()->attributes->get('csp_nonce') }}">
(()=>{const panel=document.getElementById('lpCookiePanel');let trigger=null;const token=@json(csrf_token());
const english=()=>document.documentElement.lang==='en';
function labels(){const en=english();document.getElementById('lpCookieTitle').textContent=en?'A small cookie with your bright spot?':'Een klein koekje bij je dagelijkse lichtpuntje?';document.getElementById('lpCookieText').textContent=en?'Necessary cookies keep the site working. With your permission, we count article reads and use Google Analytics to understand visits and improve Lichtpuntjes. You can use the site without statistics and change your choice through Cookie settings at any time. We remember your choice for 180 days.':'Noodzakelijke cookies laten de site werken. Met jouw toestemming tellen we gelezen berichten en gebruiken we Google Analytics om bezoeken te begrijpen en Lichtpuntjes te verbeteren. Ook zonder statistieken kun je de site gebruiken. Je kunt je keuze altijd wijzigen via Cookie-instellingen. We onthouden je keuze 180 dagen.';panel.querySelector('[data-cookie-choice="no"]').textContent=en?'Necessary only':'Alleen noodzakelijk';panel.querySelector('[data-cookie-choice="yes"]').textContent=en?'Allow visitor statistics':'Sta bezoekersstatistieken toe';document.getElementById('lpCookiePrivacy').href='/privacy?lang='+(en?'en':'nl');document.querySelectorAll('[data-cookie-settings]').forEach(b=>b.textContent=en?'Cookie settings':'Cookie-instellingen');}
document.querySelectorAll('[data-cookie-settings]').forEach(b=>b.addEventListener('click',()=>{trigger=b;panel.hidden=false;labels();panel.querySelector('button').focus();}));
panel.querySelectorAll('[data-cookie-choice]').forEach(b=>b.addEventListener('click',async()=>{const buttons=panel.querySelectorAll('button');buttons.forEach(x=>x.disabled=true);document.getElementById('lpCookieError').textContent='';try{const r=await fetch('/cookies/keuze',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({statistics:b.dataset.cookieChoice==='yes'})});if(!r.ok)throw Error();const result=await r.json();if(result.saved!==true||typeof result.statistics!=='boolean')throw Error();panel.hidden=true;document.dispatchEvent(new CustomEvent('lichtpunt:statistics-consent',{detail:{allowed:result.statistics}}));if(trigger)trigger.focus();}catch(e){document.getElementById('lpCookieError').textContent=english()?'Could not save. Refresh the page and try again.':'Opslaan lukte niet. Vernieuw de pagina en probeer opnieuw.';}finally{buttons.forEach(x=>x.disabled=false);}}));
new MutationObserver(labels).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});labels();})();
</script>
